@maddie_api.route('/vault/access-policy', methods=['PUT'])
@require_jwt(['maddie:vault:admin'])
def update_access_policy():
    data = request.get_json()

    required_fields = ['story_id', 'beneficiary', 'access_level']
    if any(field not in data for field in required_fields):
        raise BadRequest(description=f"Missing required fields: {required_fields}")

    if 'email' not in data['beneficiary'] or 'relationship' not in data['beneficiary']:
        raise BadRequest(description="Beneficiary must contain email and relationship")

    timestamp = datetime.utcnow().isoformat() + 'Z'

    attestation_id = append_witness_event(
        actor=request.user['sub'],
        event_type='access_policy_update',
        pre_state_hash=str(uuid.uuid4()),
        post_state_hash=str(uuid.uuid4()),
        timestamp=timestamp,
        metadata={
            'story_id': data['story_id'],
            'beneficiary': data['beneficiary'],
            'access_level': data['access_level']
        }
    )

    return jsonify({'attestation_id': attestation_id})

@maddie_api.route('/query/timeline', methods=['GET'])
@require_jwt(['maddie:query:timeline'])
def query_timeline():
    start = request.args.get('start')
    end = request.args.get('end')

    try:
        start_dt = datetime.fromisoformat(start) if start else None
        end_dt = datetime.fromisoformat(end) if end else None
    except ValueError:
        raise BadRequest(description="Invalid date format. Use ISO8601")

    results = {
        'events': [
            {
                'timestamp': datetime.utcnow().isoformat() + 'Z',
                'summary': "Sample event",
                'attestation_chain': [str(uuid.uuid4())]
            }
        ]
    }

    return jsonify(results)

@maddie_api.errorhandler(Unauthorized)
def handle_unauthorized(e):
    return jsonify({
        'error': 'unauthorized',
        'attestation_required': False,
        'valid_scopes': ['maddie:ingest:raw', 'maddie:vault:admin', 'maddie:query:timeline']
    }), 401

@maddie_api.errorhandler(BadRequest)
def handle_bad_request(e):
    return jsonify({
        'error': 'invalid_request',
        'attestation_required': False,
        'valid_scopes': []
    }), 400
